namespace tnt::move::worker {
namespace {
[[noreturn]] void Bad(){throw std::runtime_error("invalid_request");}
bool Hex64(const std::string&s){return s.size()==64&&std::all_of(s.begin(),s.end(),[](char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f');});}
unsigned long long Number(const std::string&s,unsigned long long max=std::numeric_limits<unsigned long long>::max()){
 if(s.empty()||s.size()>20)Bad();unsigned long long n=0;for(char c:s){if(c<'0'||c>'9'||n>(max-(c-'0'))/10)Bad();n=n*10+c-'0';}return n;
}
class Reader { std::istream& in_;size_t total_=0;public:explicit Reader(std::istream& in):in_(in){}std::string Line(){std::string s;char c;while(in_.get(c)){if(++total_>16384||s.size()>1024||c=='\r'||c=='\0')Bad();if(c=='\n')return s;s.push_back(c);}Bad();}std::string Field(const char* name){std::string line=Line(),prefix=std::string(name)+" ";if(line.rfind(prefix,0)!=0||line.size()==prefix.size())Bad();return line.substr(prefix.size());}};
std::string Canonical(const Bytes& raw){Fields fields;std::string reason;if(!DecodeDataset(raw,fields,reason))Bad();std::string out;for(const auto& [type,value]:fields){out+=char(type);out+=char(value.size());out.append(reinterpret_cast<const char*>(value.data()),value.size());}for(auto& [_,value]:fields)Wipe(value);return out;}
std::string NodeIdentity(const Node& n){return n.id+"/"+std::to_string(n.pid)+"/"+std::to_string(n.birth)+";";}
}
Input ReadInput(){Reader r(std::cin);if(r.Line()!="TNT-APP-MOVE/1")Bad();Input x;x.mode=r.Field("mode");if(x.mode!="inspect"&&x.mode!="dispatch"&&x.mode!="observe")Bad();x.operation=r.Field("operation_id");x.review=r.Field("review_revision");x.source_generation=Number(r.Field("source_generation"));x.target_generation=Number(r.Field("target_generation"));x.session=r.Field("session_id");x.discovery=r.Field("discovery_revision");x.connectivity=r.Field("connectivity_revision");for(auto s:{x.operation,x.review,x.session,x.discovery,x.connectivity})if(!Hex64(s))Bad();std::string src=r.Field("source_dataset"),dst=r.Field("target_dataset");bool ok=DecodeHex(src,x.source_dataset)&&DecodeHex(dst,x.target_dataset);std::fill(src.begin(),src.end(),'0');std::fill(dst.begin(),dst.end(),'0');if(!ok)Bad();x.manifest=r.Field("fixture_manifest");unsigned count=Number(r.Field("source_count"),8);if(!count)Bad();for(unsigned i=0;i<count;++i){auto id=r.Field("source_node");if(!Hex64(id))Bad();x.source_ids.push_back(id);}x.target_id=r.Field("target_node");if(!Hex64(x.target_id))Bad();x.delay=Number(r.Field("delay_ms"),600000);x.inventory=r.Field("inventory_attestation");if(!Hex64(x.inventory))Bad();x.lifecycle_directory=r.Field("lifecycle_directory");x.fenced_at_ms=Number(r.Field("fenced_at_ms"));x.expected=r.Field("expected_binding");if(x.expected!="-"&&!Hex64(x.expected))Bad();if(r.Line()!="END")Bad();if(x.manifest.empty()||x.manifest[0]!='/'||x.lifecycle_directory.empty()||x.lifecycle_directory[0]!='/')Bad();if(x.mode=="dispatch"&&x.expected=="-")Bad();return x;}
Fixture ReadFixture(const Input& x){auto slash=x.manifest.rfind('/');if(slash==x.manifest.npos||slash==0)throw std::runtime_error("fixture_untrusted");auto parent=x.manifest.substr(0,slash);struct stat pst{};if(lstat(parent.c_str(),&pst)||!S_ISDIR(pst.st_mode)||pst.st_uid!=geteuid()||(pst.st_mode&077)!=0)throw std::runtime_error("fixture_untrusted");int fd=open(x.manifest.c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW);if(fd<0)throw std::runtime_error("fixture_unavailable");struct stat st{};if(fstat(fd,&st)||!S_ISREG(st.st_mode)||st.st_uid!=geteuid()||(st.st_mode&077)!=0||st.st_size>4096){close(fd);throw std::runtime_error("fixture_untrusted");}std::string body(st.st_size,'\0');auto n=read(fd,body.data(),body.size());close(fd);if(n!=static_cast<ssize_t>(body.size()))throw std::runtime_error("fixture_unavailable");std::istringstream f(body);Reader r(f);if(r.Line()!="TNT-FIXTURE/1")Bad();Fixture fixture;fixture.id=r.Field("fixture_id");if(!Hex64(fixture.id))Bad();unsigned count=Number(r.Field("source_count"),8);if(count!=x.source_ids.size())Bad();auto parse=[](const std::string& line,const std::string& expected){std::istringstream s(line);Node n;std::string pid,birth,port,extra;s>>n.id>>pid>>birth>>port;if(s>>extra||!Hex64(n.id)||n.id!=expected)Bad();n.pid=Number(pid,UINT32_MAX);n.birth=Number(birth);n.port=Number(port,65535);if(!n.pid||!n.birth||!n.port)Bad();return n;};for(unsigned i=0;i<count;++i)fixture.sources.push_back(parse(r.Field("source_node"),x.source_ids[i]));fixture.target=parse(r.Field("target_node"),x.target_id);fixture.connectivity_checked_at_ms=Number(r.Field("connectivity_checked_at_ms"));auto v=r.Field("connectivity_verified");if(v!="yes"&&v!="no")Bad();fixture.connectivity_verified=v=="yes";v=r.Field("discard_set_result");if(v!="yes"&&v!="no")Bad();fixture.discard_set_result=v=="yes";if(r.Line()!="END")Bad();auto now=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();if(!fixture.connectivity_verified||fixture.connectivity_checked_at_ms>static_cast<unsigned long long>(now)||static_cast<unsigned long long>(now)-fixture.connectivity_checked_at_ms>30000)throw std::runtime_error("connectivity_stale");return fixture;}
std::string Sha256(const std::string& input){unsigned char digest[32];if(mbedtls_sha256(reinterpret_cast<const unsigned char*>(input.data()),input.size(),digest,0)!=0)throw std::runtime_error("hash_failed");std::ostringstream o;for(unsigned char c:digest)o<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(c);return o.str();}
std::string DatasetCommitment(const Bytes& raw){auto canonical=Canonical(raw);auto digest=Sha256(canonical);volatile char* p=canonical.data();for(size_t i=0;i<canonical.size();++i)p[i]=0;return digest;}
std::string Binding(const Input& x,const Fixture& f){std::string v="TNT-APP-MOVE-BINDING/1\n"+x.operation+"\n"+x.review+"\n"+std::to_string(x.source_generation)+"\n"+std::to_string(x.target_generation)+"\n"+x.session+"\n"+x.discovery+"\n"+x.connectivity+"\n"+x.inventory+"\n"+f.id+"\n"+DatasetCommitment(x.source_dataset)+"\n"+DatasetCommitment(x.target_dataset)+"\n";for(auto& n:f.sources)v+=NodeIdentity(n);v+=NodeIdentity(f.target);v+=std::to_string(x.delay);v+=f.discard_set_result?"discard":"normal";return Sha256(v);}
std::string RecoveryBinding(const Input& x,const Fixture& f){std::string v="TNT-APP-MOVE-RECOVERY/1\n"+x.operation+"\n"+f.id+"\n"+DatasetCommitment(x.source_dataset)+"\n"+DatasetCommitment(x.target_dataset)+"\n";for(auto& n:f.sources)v+=NodeIdentity(n);v+=NodeIdentity(f.target);v+=std::to_string(x.delay);v+=f.discard_set_result?"discard":"normal";return Sha256(v);}
}
